BEGIN; DO $$ BEGIN IF to_regprocedure('public.adjust_shipment_items_core_20260723(uuid,jsonb,text)') IS NULL THEN RAISE EXCEPTION 'Thieu core adjust_shipment_items_core_20260723. Can kiem tra ban dieu chinh chuyen dang chay truoc.'; END IF; END $$; CREATE OR REPLACE FUNCTION public.adjust_shipment_items_v1(p_shipment_id uuid,p_lines jsonb,p_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_result jsonb; v_numbered_count integer; v_active_count integer; BEGIN IF auth.uid() IS NULL OR NOT public.is_admin() THEN RAISE EXCEPTION 'Chi Admin moi co quyen chinh sua phieu giao hang.' USING ERRCODE='42501'; END IF; v_result:=public.adjust_shipment_items_core_20260723(p_shipment_id,p_lines,p_reason); UPDATE public.inventory_transactions t SET shipment_line_no=x.line_no::integer FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS x(item,line_no) WHERE t.shipment_id=p_shipment_id AND t.delivery_plan_id=NULLIF(x.item->>'plan_id','')::uuid AND t.tx_type='out' AND t.adjusted_from_transaction_id IS NULL AND t.deleted_at IS NULL; GET DIAGNOSTICS v_numbered_count=ROW_COUNT; SELECT count(*) INTO v_active_count FROM public.inventory_transactions t WHERE t.shipment_id=p_shipment_id AND t.tx_type='out' AND t.adjusted_from_transaction_id IS NULL AND t.deleted_at IS NULL; IF v_numbered_count<>v_active_count THEN RAISE EXCEPTION 'Khong luu du thu tu dong sau dieu chinh; toan bo thao tac da duoc hoan tac.'; END IF; RETURN v_result; END $$; REVOKE ALL ON FUNCTION public.adjust_shipment_items_v1(uuid,jsonb,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.adjust_shipment_items_v1(uuid,jsonb,text) TO authenticated; NOTIFY pgrst,'reload schema'; COMMIT;
